#include<iostream>
#include<cstdio>
#include<algorithm>
#include<cmath>
using namespace std;
int t,n,m,l,lim;
int d[100010],v[100010],a[100010],p[100010];
const double eps=1e-6;
struct seg{
    int l,r;
}b[100010];
bool cmp(const seg &x,const seg &y){
    return x.r<y.r;
}
inline int fl(double x)
{
    if(x-(int)x<eps)return (int)x-1;
    else return (int)x;
}
inline int ce(double x)
{
    if((int)x+1-x<eps)return (int)x+2;
    else return (int)x+1;
}
int main()
{


    scanf("%d",&t);
    while(t--)
    {
        scanf("%d%d%d%d",&n,&m,&l,&lim);
        for(int i=1;i<=n;i++)
            scanf("%d%d%d",&d[i],&v[i],&a[i]);
        for(int i=1;i<=m;i++)scanf("%d",&p[i]);
        for(int i=1;i<=n;i++)
        {
            if(a[i]>0)
            {
                if(v[i]>lim)
                {
                    b[i].l=d[i];
                    b[i].r=l;
                }
                else
                {
                    double tt=(lim-v[i])*1.0/a[i];
                    b[i].l=min(l+1,ce(d[i]+v[i]*tt+0.5*a[i]*tt*tt));
                    b[i].r=l;

                }
            }
            else if(a[i]==0)
            {
                if(v[i]>lim)
                {
                    b[i].l=d[i];
                    b[i].r=l;
                }
                else
                {
                    b[i].l=1;
                    b[i].r=0;
                }
            }
            else if(v[i]>lim)
            {
                double tt=(lim-v[i])*1.0/a[i];
                b[i].l=d[i];
                b[i].r=min(l,fl(d[i]+v[i]*tt+0.5*a[i]*tt*tt));

            }
            else
            {
                b[i].l=1;
                b[i].r=0;
            }
        }
        sort(b+1,b+n+1,cmp);
        int now=0,cnt=0,ans=0;
        p[0]=-1;
        for(int i=1;i<=n;i++)
        {
            int pos=lower_bound(p+1,p+m+1,b[i].l)-p;
            if(pos>m||p[pos]>b[i].r)continue;
            if(p[now]>=b[i].l)
            {
                cnt++;
                continue;
            }
            int nnow=now;
            while(nnow<m&&p[nnow+1]<=b[i].r)nnow++;
            if(p[nnow]<b[i].l)continue;
            now=nnow,ans++,cnt++;
        }
        printf("%d %d\n",cnt,m-ans);
    }
    return 0;
}

#include <bits/stdc++.h>
#define lowbit(o) o & -o
#define pb push_back
#define x first
#define y second
using namespace std;
typedef long long LL;
typedef unsigned long long ULL;
typedef pair<int, int> PII;
typedef pair<LL, LL> PLL;
const int N = 100005;
const int mod = 998244353;
const int inf = 5e5;
const LL INF = 1e18;
int d[N], v[N], a[N], p[N];
struct Line{
	int l, r;
}c[N];
int w[N << 2], Lmax[N], f[N];
bool cmp(Line A,Line B)
{
	if (A.r != B.r)
		return A.r < B.r;
	return A.l < B.l;
}
LL calc(LL v,LL a,LL d,LL pos)
{
	LL s = pos - d;
	return v * v + 2 * a * s;
}
inline void pushup(int u)
{
	w[u] = min(w[u << 1], w[u << 1 | 1]);
}
void build(int u,int l,int r)
{
	if (l == r)
	{
		w[u] = 1000000;
		if (!l)
			w[u] = 0;
		return;
	}
	int mid = (l + r) >> 1;
	build(u << 1, l, mid);
	build(u << 1 | 1, mid + 1, r);
	pushup(u);
}
void update(int u,int l,int r,int x,int v)
{
	if (l == r)
	{
		w[u] = v;
		return;
	}
	int mid = (l + r) >> 1;
	if (x <= mid)
		update(u << 1, l, mid, x, v);
	else
		update(u << 1 | 1, mid + 1, r, x, v);
	pushup(u);
}
int query(int u,int l,int r,int L,int R)
{
	if (L <= l && r <= R)
		return w[u];
	int mid = (l + r) >> 1, res = 1000000;
	if (L <= mid)
		res = query(u << 1, l, mid, L ,R);
	if (mid < R)
		res = min(res, query(u << 1 | 1, mid + 1, r, L, R));
	return res;
}
void work()
{
	int n, m, L;
	LL V;
	cin >> n >> m >> L >> V;
	for (int i=1;i<=n;i++)
		cin >> d[i] >> v[i] >> a[i];
	for (int i=1;i<=m;i++)
		cin >> p[i];
	int tot = 0;
	for (int i=1;i<=n;i++)
	{
		if (p[m] < d[i])
			continue;
		int l = lower_bound(p + 1, p + m + 1, d[i]) - p, r = m, res = 0;
		if (a[i] > 0)
		{
			while (l <= r)
			{
				int mid = (l + r) >> 1;
				if (calc(v[i], a[i], d[i], p[mid]) > V * V)
					res = mid, r = mid - 1;
				else
					l = mid + 1;
			}
			if (res)
			{
				c[++ tot] = {res, m};

			}
		}
		else if (a[i] == 0)
		{
			if (v[i] > V)
				c[++ tot] = {l, m};

		}
		else
		{
			int L = l;
			while (l <= r)
			{
				int mid = (l + r) >> 1;
				if (calc(v[i], a[i], d[i], p[mid]) > V * V)
					res = mid, l = mid + 1;
				else
					r = mid - 1;
			}
			if (res)
			{
				c[++ tot] = {L, res};

			}
		}
	}
	cout << tot << ' ';
	if (!tot)
	{
		cout << m << '\n';
		return;
	}
	sort(c + 1, c + tot + 1, cmp);
	for (int i=1;i<=tot;i++)
		Lmax[i] = max(Lmax[i - 1], c[i].l);
	build(1, 0, m);
	for (int i=1;i<=m;i++)
	{
		int l = 1, r = tot, res = 0;
		while (l <= r)
		{
			int mid = (l + r) >> 1;
			if (c[mid].r < i)
				res = mid, l = mid + 1;
			else
				r = mid - 1;
		}
		f[i] = query(1, 0, m, Lmax[res], i - 1) + 1;
		update(1, 0, m, i, f[i]);
	}
	int ans = 1000000;
	for (int i=1;i<=m;i++)
		if (i >= Lmax[tot])
			ans = min(ans, f[i]);
	cout << m - ans << '\n';
}
signed main()
{
    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
    int _T = 1;
    cin >> _T;
    while (_T--)
        work();
    return 0;
}
